import { test, expect } from '@playwright/test';

test.describe('Alert Dialog Interaction Blocking', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should block interaction with page when alert dialog is open', async ({ page }) => {
    // Open alert dialog
    const alertButton = page.getByRole('button', { name: /open alert/i });
    await alertButton.click();

    // Verify alert dialog is visible
    const alertDialog = page.locator('[data-testid="alert-dialog"]');
    await expect(alertDialog).toBeVisible();

    // Verify interaction is blocked
    const dashboardButton = page.getByRole('button', { name: /dashboard/i });
    await expect(dashboardButton).not.toBeEnabled();

    // Verify alert dialog is blocking
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeDisabled();

    // Verify alert dialog is still visible
    await expect(alertDialog).toBeVisible();

    // Verify alert dialog has correct content
    const alertMessage = page.getByText(/error/i);
    await expect(alertMessage).toBeVisible();

    // Verify close button is present and clickable
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Close alert dialog
    await closeButton.click();

    // Verify page interaction is restored
    await expect(dashboardButton).toBeEnabled();
    await expect(mainContent).not.toBeDisabled();

    // Verify alert dialog is no longer visible
    await expect(alertDialog).not.toBeVisible();
  });

  test('should allow interaction with page when alert dialog is closed', async ({ page }) => {
    // Open alert dialog
    const alertButton = page.getByRole('button', { name: /open alert/i });
    await alertButton.click();

    // Verify alert dialog is visible
    const alertDialog = page.locator('[data-testid="alert-dialog"]');
    await expect(alertDialog).toBeVisible();

    // Verify interaction is blocked
    const dashboardButton = page.getByRole('button', { name: /dashboard/i });
    await expect(dashboardButton).not.toBeEnabled();

    // Verify alert dialog is blocking
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeDisabled();

    // Verify alert dialog is still visible
    await expect(alertDialog).toBeVisible();

    // Verify alert dialog has correct content
    const alertMessage = page.getByText(/error/i);
    await expect(alertMessage).toBeVisible();

    // Close alert dialog
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify page interaction is restored
    await expect(dashboardButton).toBeEnabled();
    await expect(mainContent).not.toBeDisabled();

    // Verify alert dialog is no longer visible
    await expect(alertDialog).not.toBeVisible();
  });
});
